-- Hyprland window and layer rules.
hl.window_rule({ name = "kitty-super-k-tiled-terminal", match = { class = "^kitty-super-k$" }, tile = true, fullscreen_state = "0 0", suppress_event = "fullscreen maximize" })
hl.window_rule({ name = "windowrule-1", match = { class = ".*" }, idle_inhibit = "fullscreen" })
hl.window_rule({ name = "windowrule-2", match = { title = ".*" }, idle_inhibit = "fullscreen" })
hl.window_rule({ name = "windowrule-3", match = { fullscreen = true }, idle_inhibit = "fullscreen" })
hl.window_rule({ name = "windowrule-4", match = { class = "^([Vv]esktop)$" }, workspace = "7" })
hl.window_rule({ name = "windowrule-5", match = { class = "^([Ff]erdium)$" }, workspace = "7", float = true, opacity = "0.9 0.7", size = "(monitor_w*0.6) (monitor_h*0.7)" })
hl.window_rule({ name = "windowrule-6", match = { class = "^(virt-manager)$" }, workspace = "6 silent" })
hl.window_rule({ name = "windowrule-7", match = { class = "^([Aa]udacious)$" }, workspace = "9 silent", opacity = "0.9 0.7" })
hl.window_rule({ name = "windowrule-8", match = { class = "([Zz]oom|onedriver|onedriver-launcher)$" }, float = true })
